// Fixed command table — actions are chosen from this allowlist only; no user
// input is ever interpolated into a shell command. The GitHub commit message is
// passed via an environment variable and expanded inside double quotes, so its
// contents can't break out into further shell parsing.
const STAGE_ACTIONS: Record<StageAction, { label: string; cmd: string; args: string[] }> = {
  docs: { label: "Publish to docs", cmd: "node", args: ["scripts/publish-docs.mjs"] },
  staging: { label: "Deploy to staging", cmd: "bash", args: ["scripts/deploy-staging.sh"] },
  production: { label: "Promote to production", cmd: "bash", args: ["scripts/promote-production.sh"] },
  github: { label: "Commit to GitHub", cmd: "bash", args: ["-c", 'git add -A && git commit -m "$NXEON_COMMIT_MSG"'] },
};

async function readLogTail(logPath: string, max = 4000): Promise<string> {
  try {
    const buf = await fs.readFile(logPath, "utf8");
    return buf.length > max ? "…" + buf.slice(-max) : buf || "(no output)";
  } catch {
    return "(log unavailable)";
  }
}

/**
 * Run a pipeline action for a card. Admin-gated. Spawns the mapped script
 * detached with output captured to a per-run log, records a start comment, and
 * (when the child exits) a completion comment with the log tail. Returns as soon
 * as the child is launched — it never waits for a long deploy to finish.
 */
export async function runCardStageAction(
  cardId: string,
  action: StageAction,
): Promise<{ error?: string; started?: boolean; logPath?: string }> {
  const admin = await requireAdmin();
  const spec = STAGE_ACTIONS[action];
  if (!spec) return { error: "Unknown action." };
  const card = await db.card.findUnique({ where: { id: cardId }, select: { id: true, title: true } });
  if (!card) return { error: "Card not found." };

  await fs.mkdir(STAGE_LOG_DIR, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const logPath = join(STAGE_LOG_DIR, `${cardId}-${action}-${stamp}.log`);

  const env: NodeJS.ProcessEnv = { ...process.env };
  if (action === "github") {
    env.NXEON_COMMIT_MSG = `board: ${card.title} (card ${cardId})`.replace(/\s+/g, " ").slice(0, 180);
  }

  const author = admin.email.split("@")[0];
  await db.cardComment.create({
    data: { cardId, authorName: author, body: `▶️ Started **${spec.label}**.\nLog: \`${logPath}\`` },
  });

  let logFd;
  try {
    logFd = await fs.open(logPath, "a");
  } catch (e) {
    return { error: `Could not open log file: ${(e as Error).message}` };
  }

  try {
    const child = spawn(spec.cmd, spec.args, {
      cwd: PROJECT_ROOT,
      env,
      detached: true,
      stdio: ["ignore", logFd.fd, logFd.fd],
    });
    child.unref();
    child.on("error", (err) => {
      logFd.close().catch(() => undefined);
      db.cardComment
        .create({ data: { cardId, authorName: "system", body: `❌ **${spec.label}** failed to start: ${err.message}` } })
        .catch(() => undefined);
    });
    child.on("exit", async (code, signal) => {
      await logFd.close().catch(() => undefined);
      const tail = await readLogTail(logPath);
      const status = code === 0 ? "✅ succeeded" : `❌ exited with ${code ?? `signal ${signal}`}`;
      await db.cardComment
        .create({ data: { cardId, authorName: "system", body: `**${spec.label}** ${status}\n\n\`\`\`\n${tail}\n\`\`\`` } })
        .catch(() => undefined);
    });
  } catch (e) {
    await logFd.close().catch(() => undefined);
    return { error: `Failed to launch: ${(e as Error).message}` };
  }

  revalidatePath("/admin/board");
  return { started: true, logPath };
}

