69	/** True only for an actual string matching `re` — RegExp#test() coerces its
70	 *  argument, so `CHAIN_RE.test(123)` would otherwise pass (stringifies to
71	 *  "123", which matches [A-Z0-9_]) and hand a NUMBER to execFile's argv array
72	 *  a few lines later. Every JSON-body-derived field is checked with this,
73	 *  never a bare `.test()`, so a type-confused value is rejected up front
74	 *  instead of surfacing as a confusing execFile error downstream. */
75	function isStr(v, re) {
76	  return typeof v === "string" && re.test(v);
77	}
