79	function isValidPort(n) {
80	  return Number.isInteger(n) && n >= 1 && n <= 65535;
81	}
82	function isValidRule(r) {
83	  return (
84	    !!r &&
85	    (r.proto === "tcp" || r.proto === "udp") &&
86	    isValidPort(r.dport) &&
87	    typeof r.destIp === "string" &&
88	    IPV4_RE.test(r.destIp) &&
89	    isValidPort(r.destPort)
90	  );
91	}
92	/** Argv fragment shared by -A/-D — mirrors lib/nat-rules.ts's ruleSpec(). */
93	function ruleSpec(r) {
94	  return ["-p", r.proto, "--dport", String(r.dport), "-j", "DNAT", "--to-destination", `${r.destIp}:${r.destPort}`];
95	}
