97	// ---- constant-time bearer check --------------------------------------------
98	function checkAuth(req) {
99	  const header = req.headers["authorization"] || "";
100	  const m = /^Bearer (.+)$/.exec(header);
101	  if (!m) return false;
102	  const presented = Buffer.from(m[1]);
103	  const expected = Buffer.from(TOKEN);
104	  // timingSafeEqual throws on a length mismatch rather than returning false —
105	  // guard it explicitly so a short/garbled header can't produce a stack trace.
106	  if (presented.length !== expected.length) return false;
107	  return crypto.timingSafeEqual(presented, expected);
108	}
