110	// ---- iptables exec — argv arrays only, NEVER a shell string ----------------
111	function iptables(args) {
112	  return new Promise((resolve, reject) => {
113	    execFile("iptables", args, { timeout: CMD_TIMEOUT_MS }, (err, stdout, stderr) => {
114	      if (err) return reject(new Error(String(stderr || err.message).trim().slice(0, 400)));
115	      resolve(stdout);
116	    });
117	  });
118	}
