123	  } catch {
124	    /* chain already exists */
125	  }
126	  try {
127	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", chain]);
128	  } catch {
129	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", chain]);
