133	function pvesmPath(storageRef) {
134	  return new Promise((resolve, reject) => {
135	    execFile("pvesm", ["path", storageRef], { timeout: 10_000 }, (err, stdout) => {
136	      if (err) return reject(new Error(`pvesm path ${storageRef}: ${err.message}`));
137	      resolve(stdout.trim());
138	    });
139	  });
140	}
