142	// ---- request body helpers ---------------------------------------------------
143	function readBody(req) {
144	  return new Promise((resolve, reject) => {
145	    let size = 0;
146	    const chunks = [];
147	    req.on("data", (c) => {
148	      size += c.length;
149	      if (size > MAX_BODY_BYTES) {
150	        reject(new Error("request body too large"));
151	        req.destroy();
152	        return;
153	      }
154	      chunks.push(c);
155	    });
156	    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
157	    req.on("error", reject);
158	  });
159	}
