182	async function handleEnsureChain(_req, res, rawBody) {
183	  const parsed = parseJson(rawBody);
184	  const chain = parsed && parsed.chain;
185	  if (!parsed || !CHAIN_RE.test(chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
