201	async function handleAddRule(_req, res, rawBody) {
202	  const parsed = parseJson(rawBody);
203	  if (!parsed || !CHAIN_RE.test(parsed.chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
204	  if (!isValidRule(parsed.rule)) return sendJson(res, 400, { error: "invalid rule" });
205	  await iptables(["-t", "nat", "-A", parsed.chain, ...ruleSpec(parsed.rule)]);
206	  sendJson(res, 200, { ok: true });
