209	async function handleDeleteRule(_req, res, rawBody) {
210	  const parsed = parseJson(rawBody);
211	  if (!parsed || !CHAIN_RE.test(parsed.chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
212	  if (!isValidRule(parsed.rule)) return sendJson(res, 400, { error: "invalid rule" });
213	  await iptables(["-t", "nat", "-D", parsed.chain, ...ruleSpec(parsed.rule)]);
214	  sendJson(res, 200, { ok: true });
215	}
