217	/** Resolve `<storage>:snippets/<filename>` via pvesm and refuse anything that
218	 *  didn't land in a real snippets directory — defense in depth beyond the
219	 *  filename/storage allowlists above. */
220	async function resolveSnippetPath(storage, filename) {
221	  const target = await pvesmPath(`${storage}:snippets/${filename}`);
222	  if (!target.includes(`${path.sep}snippets${path.sep}`) && !target.endsWith(`${path.sep}snippets`)) {
