228	async function handleWriteSnippet(_req, res, rawBody) {
229	  const parsed = parseJson(rawBody);
230	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
231	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
232	  if (typeof parsed.content !== "string" || parsed.content.length > MAX_BODY_BYTES) {
233	    return sendJson(res, 400, { error: "invalid content" });
234	  }
235	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
236	  fs.mkdirSync(path.dirname(target), { recursive: true });
