241	async function handleDeleteSnippet(_req, res, rawBody) {
242	  const parsed = parseJson(rawBody);
243	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
244	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
245	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
246	  fs.rmSync(target, { force: true });
