250	async function handleDnatCheck(_req, res, address) {
251	  if (!IPV4_RE.test(address || "")) return sendJson(res, 400, { error: "invalid address" });
252	  const output = await iptables(["-t", "nat", "-S", "PREROUTING"]);
253	  const hasLiveDnatRule = output.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
254	  sendJson(res, 200, { hasLiveDnatRule });
255	}
