259	async function route(req, res) {
260	  const url = new URL(req.url, `https://${req.headers.host || "localhost"}`);
261	  const { pathname, searchParams } = url;
262	
263	  if (req.method === "GET" && pathname === "/v1/health") return handleHealth(req, res);
264	
265	  if (req.method === "POST" && pathname === "/v1/nat/ensure-chain") return handleEnsureChain(req, res, await readBody(req));
266	
267	  const chainMatch = /^\/v1\/nat\/chain\/([^/]+)$/.exec(pathname);
268	  if (req.method === "GET" && chainMatch) return handleListChain(req, res, decodeURIComponent(chainMatch[1]));
269	
270	  if (req.method === "POST" && pathname === "/v1/nat/rule") return handleAddRule(req, res, await readBody(req));
271	  if (req.method === "DELETE" && pathname === "/v1/nat/rule") return handleDeleteRule(req, res, await readBody(req));
272	
273	  if (req.method === "POST" && pathname === "/v1/snippet") return handleWriteSnippet(req, res, await readBody(req));
274	  if (req.method === "DELETE" && pathname === "/v1/snippet") return handleDeleteSnippet(req, res, await readBody(req));
275	
276	  if (req.method === "GET" && pathname === "/v1/iptables/dnat-check") return handleDnatCheck(req, res, searchParams.get("address"));
277	
278	  sendJson(res, 404, { error: "not found" });
279	}
