  if (file.size > cap) return NextResponse.json({ error: `File too large (max ${Math.round(cap / 1024 / 1024)} MB)` }, { status: 413 });

  const buf = Buffer.from(await file.arrayBuffer());

  // A file that CLAIMS to be an image is served inline by the [id] route, so it
  // must be a real raster image — never a scripted SVG (stored XSS in the
  // portal origin). Verify by byte signature; SVG has no signature and isn't
  // allow-listed, so it's rejected here (same reasoning as the board's route).
  if (kind === "IMAGE") {
    const sniffed = sniffImageMime(buf);
    if (!sniffed || mime === "image/svg+xml" || !isAllowedImageMime(mime)) {
      return NextResponse.json({ error: "Only PNG, JPEG, GIF, or WEBP images are allowed." }, { status: 400 });
    }
    mime = sniffed;
    kind = kindFor(mime);
  }

  const ext = (file.name.match(/\.[A-Za-z0-9]{1,8}$/)?.[0] ?? "").toLowerCase();
  const storedName = `${randomBytes(12).toString("hex")}${ext}`;
  const dir = join(WORK_UPLOAD_DIR, taskId);
  try {
    await fs.mkdir(dir, { recursive: true });
    await fs.writeFile(join(dir, storedName), buf);
  } catch (e) {
    console.error("[work] attachment write failed:", e);
    return NextResponse.json(
      { error: `Couldn't save the file (${(e as NodeJS.ErrnoException)?.code ?? "write error"}). Ensure ${WORK_UPLOAD_DIR} is writable by the web user.` },
      { status: 500 },
    );
  }

  const att = await db.workTaskAttachment.create({
    data: { taskId, filename: file.name.slice(0, 200), storedName, mime, sizeBytes: file.size, kind, uploadedById: actor.id },
  });
  await db.auditLog.create({ data: { userId: actor.id, action: "task.attachment.add", detail: `${taskId}: ${att.filename}` } });
  return NextResponse.json({ id: att.id, filename: att.filename, kind, mime, sizeBytes: att.sizeBytes, url: `/api/work/attachments/${att.id}` });
}

